content = read_file(file_path="address-change.txt")
found = ask(value=content, question="Does this text clearly state a new street address or city for the account holder? Answer true only if it does.", type="bool")
if found:
    street = ask(value=content, question="What is the new street address for the account holder? Return an empty string if the text does not give one.", type="str")
    city = ask(value=content, question="What is the new city for the account holder? Return an empty string if the text does not give one.", type="str")
    if street != "" and city != "":
        update_user_info(street=street, city=city)
        respond("Your street address and city have been updated from address-change.txt.")
    elif street != "":
        update_user_info(street=street)
        respond("Your street address has been updated from address-change.txt. No city change was found.")
    elif city != "":
        update_user_info(city=city)
        respond("Your city has been updated from address-change.txt. No street change was found.")
    else:
        respond("address-change.txt did not contain a usable street or city, so your account information was not changed.")
